#!/usr/bin/env python3
"""
Generates chunks.h for the on-device harness.

Each case is one luaL_loadbuffer call the real Cocos engine would make. The encrypted ones are
encrypted with the repo's own tests/conftest.py xxtea_encrypt (same KEY/SIGN as the pytest suite),
so the C xxtea_decrypt in the harness has to agree with it for the chunk to compile at all.

Chunk-name forms are taken from cocos2d-x v3 CCLuaStack.cpp:
  * executeScriptFile   -> FileUtils::fullPathForFilename(), no '@' prefix
  * loadChunksFromZIP   -> zip entry, extension stripped, '/' and '\\' turned into '.'
  * hot-updated scripts -> an absolute path in the app's writable dir
"""
from __future__ import annotations

import subprocess
import sys
from pathlib import Path

REPO = Path(__file__).resolve().parents[4]  # this file: <repo>/tests/fixtures/android/harness/
sys.path.insert(0, str(REPO))
from tests.conftest import KEY_TEXT, SIGN, xxtea_encrypt  # noqa: E402
from coconuts.ciphers import normalize_key  # noqa: E402

LUA_SRC = b"local M = {}\nfunction M.run() return 42 end\nreturn M\n"


def enc(data: bytes) -> bytes:
    return SIGN + xxtea_encrypt(data, normalize_key(KEY_TEXT))


def c_bytes(data: bytes) -> str:
    return ",".join(str(b) for b in data)


def main() -> int:
    luac = sys.argv[1] if len(sys.argv) > 1 else ""
    out = Path(sys.argv[2]) if len(sys.argv) > 2 else Path("chunks.h")

    bytecode = b""
    if luac:
        src = out.parent / "_tmp_chunk.lua"
        src.write_bytes(LUA_SRC)
        dst = out.parent / "_tmp_chunk.luac"
        subprocess.run([luac, "-s", "-o", str(dst), str(src)], check=True)
        bytecode = dst.read_bytes()
        src.unlink()
        dst.unlink()

    # (name, plaintext, encrypted, label)
    cases: list[tuple[str, bytes, bool, str]] = [
        ("assets/src/main.lua", LUA_SRC, True,
         "executeScriptFile: APK asset full path"),
        ("assets/src/app/views/MainScene.lua", LUA_SRC, True,
         "executeScriptFile: nested asset path"),
        ("app.views.MainScene", LUA_SRC, True,
         "loadChunksFromZIP: dotted module name"),
        ("/data/user/0/com.example.game/files/src/hot.lua", LUA_SRC, True,
         "hot update: absolute path in the writable dir"),
        ("assets/src/plain.lua", LUA_SRC, False,
         "shipped in the clear: luaLoadBuffer else-branch"),
        ("assets/src/bom.lua", b"\xef\xbb\xbf" + LUA_SRC, True,
         "UTF-8 BOM: hook must see the post-skipBOM pointer"),
    ]
    if bytecode:
        cases.append(("assets/src/compiled.luac", bytecode, True,
                      "real stripped Lua bytecode (NULs, 0x1b magic)"))

    lines = [
        "/* Generated by gen_chunks.py - do not edit. */",
        "#ifndef HARNESS_CHUNKS_H",
        "#define HARNESS_CHUNKS_H",
        "",
        "typedef struct {",
        "    const char *name;",
        "    const unsigned char *data;",
        "    unsigned int size;",
        "    int encrypted;",
        "    unsigned int plain_size;   /* expected post-decrypt length the hook should report */",
        "    const char *label;",
        "} chunk_case_t;",
        "",
        f'#define HARNESS_XXTEA_KEY "{KEY_TEXT.decode()}"',
        f"#define HARNESS_XXTEA_KEY_LEN {len(KEY_TEXT)}",
        f'#define HARNESS_XXTEA_SIGN "{SIGN.decode()}"',
        f"#define HARNESS_XXTEA_SIGN_LEN {len(SIGN)}",
        "",
    ]
    for i, (name, plain, encrypted, _label) in enumerate(cases):
        blob = enc(plain) if encrypted else plain
        lines.append(f"static const unsigned char chunk_{i}[] = {{{c_bytes(blob)}}};")
    lines.append("")
    lines.append("static const chunk_case_t harness_chunks[] = {")
    for i, (name, plain, encrypted, label) in enumerate(cases):
        blob = enc(plain) if encrypted else plain
        # What the hook should see: the plaintext, minus a BOM the engine skips.
        seen = plain[3:] if plain.startswith(b"\xef\xbb\xbf") else plain
        esc = name.replace("\\", "\\\\").replace('"', '\\"')
        lines.append(f'    {{"{esc}", chunk_{i}, {len(blob)}u, {1 if encrypted else 0}, '
                     f'{len(seen)}u, "{label}"}},')
    lines.append("};")
    lines.append(f"#define HARNESS_CHUNK_COUNT {len(cases)}")
    lines.append("")
    lines.append("#endif")
    out.write_text("\n".join(lines) + "\n")

    print(f"wrote {out} with {len(cases)} cases"
          f"{' (incl. real bytecode)' if bytecode else ' (no luac: bytecode case skipped)'}")
    for name, plain, encrypted, label in cases:
        seen = plain[3:] if plain.startswith(b"\xef\xbb\xbf") else plain
        print(f"  {name!r:55} enc={int(encrypted)} plain={len(seen):4d}  {label}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
